#include <iostream>
#include <iomanip>

void displayBits(unsigned value) {
    const int SHIFT = static_cast<int>(8 * sizeof(unsigned) - 1);
    const unsigned MASK = 1u << SHIFT;

    std::cout << std::setw(10) << value << " = ";
    for (int i = 1; i <= SHIFT + 1; ++i) {
        std::cout << ((value & MASK) ? '1' : '0');
        value <<= 1;
        if (i % 8 == 0) {
            std::cout << ' ';
        }
    }
    std::cout << '\n';
}

int main() {
    unsigned number1 = 960;

    std::cout << "The result of left shifting\n";
    displayBits(number1);
    std::cout << "8 bit positions using the left-shift operator is\n";
    displayBits(number1 << 8);

    std::cout << "\nThe result of right shifting\n";
    displayBits(number1);
    std::cout << "8 bit positions using the right-shift operator is\n";
    displayBits(number1 >> 8);

    return 0;
}

#include <iostream>
#include <iomanip>

struct BitCard {
    unsigned face : 4;  // 4 bits: 0 - 15
    unsigned suit : 2;  // 2 bits: 0 - 3
    unsigned color : 1; // 1 bit:  0 - 1
};

int main() {
    BitCard card1;
    card1.face = 12; // King
    card1.suit = 3;  // Spades
    card1.color = 1; // Black

    std::cout << "BitCard structure size: " << sizeof(BitCard) << " byte(s)\n";
    std::cout << "Card face:  " << std::setw(2) << card1.face << "\n";
    std::cout << "Card suit:  " << std::setw(2) << card1.suit << "\n";
    std::cout << "Card color: " << std::setw(2) << card1.color << "\n";

    return 0;
}
